import type { HotkeyTable } from "~/core/hotkeys/KeyHook";

/**
 * gen4's F-key table, lifted from the `keyhook.registerShortCut` calls in its
 * `mounted` (plan 2.4, decision 7: per-gen tables preserved, quirks included).
 *
 * gen4's own shape: F13 shows IVs (no DV/Hidden Power cycle), F16 is Automatic with no
 * Badge Boosts cycle, F17-F19 switch the right panel, F20 toggles the bonk counter, and
 * F21/F22 log that they are unused -- which is still a binding, so it stays.
 *
 * `vm` is the overlay component instance, which is what `this` was. Generated by
 * tools/port/lift-gen4.py from the `keyhook.registerShortCut` block; do not edit.
 */
export function gen4Hotkeys(vm: any): HotkeyTable {
    return {
        F13: async () => { // Show IVs
            console.log("Key: F13 pressed: DVs displayed.")
            vm.stats_setting = "IVs";
        },
        F14: async () => { // Show EVs
            console.log("Key: F14 pressed: Stat experience displayed.")
            if (vm.stats_setting == "EVs") {
                vm.stats_setting = "Detailed EVs";
                return
            }
            vm.stats_setting = "EVs";
        },
        F15: async () => { // Show Base Stats
            console.log("Key: F15 pressed. Base Stats displayed.")
            vm.stats_setting = "Base Stats";
        },
        F16: async () => { // Automatic
            console.log("Key: F16 pressed. Stats are displaying automatically now.")
            vm.stats_setting = "Automatic";
        },
        F17: async () => { // Inventory
            console.log("Key: F17 pressed. Automatic battle graphics will be displayed.")
            vm.right_panel = "Battle Graphic";
        },
        F18: async () => { // Trainer Graphic during Battle
            console.log("Key: F18 pressed. Inventory displayed.")
            vm.right_panel = "Inventory";
        },
        F19: async () => { // Trainer Graphic during Battle
            console.log("Key: F19 pressed. Movepool displayed.")
            vm.right_panel = "Movepool";
        },
        F20: async () => { // Trainer Graphic during Battle
            console.log(`Key: F20 pressed. Bonk counter displayed. (Bonk = ${vm.bonk})`)
            vm.bonk = !vm.bonk;
        },
        F21: async () => { // Trainer Graphic during Battle
            console.log(`Key: F21 pressed. This shortcut is currently unused...`)
        },
        F22: async () => { // Trainer Graphic during Battle
            console.log(`Key: F22 pressed. This shortcut is currently unused...`)
        },
        F23: async () => { // Clear Timer and Metrics
            vm.newRun()
        },
        F24: async () => { // Pause
            vm.pauseUnpauseTime()
        },
    };
}
